// The kit's tool plan (ui-kit `normalizeToolCatalog` + `planRunTools`, backlog 0033) with no
// layers gives the desktop's lists for the same gateway answer: the tools offered and the
// auto / ask split (cases generated BY the desktop's controller,
// web/scripts/gen_tool_policy_parity.py). Order is the kit's (by name), not part of the contract.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { normalizeToolCatalog, planRunTools, withRunTools } from "@abstractframework/ui-kit";
import { describe, expect, it } from "vitest";

import { buildRunInputData } from "./run_input";

type Lists = { allowed_tools: string[]; tool_policy: { auto_approve_tools: string[]; require_approval_tools: string[] } };
type Case = { name: string; discovery: unknown; expected: Lists };
const cases: Case[] = JSON.parse(readFileSync(resolve(__dirname, "__fixtures__/tool_policy_parity.json"), "utf8"));
const sorted = (a: string[]) => [...a].sort();

describe("planRunTools with no layers = the desktop's lists", () => {
  for (const c of cases) {
    it(c.name, () => {
      const plan = planRunTools(normalizeToolCatalog(c.discovery));
      expect(sorted(plan.tools)).toEqual(sorted(c.expected.allowed_tools));
      expect(sorted(plan.approval.auto)).toEqual(sorted(c.expected.tool_policy.auto_approve_tools));
      expect(sorted(plan.approval.ask)).toEqual(sorted(c.expected.tool_policy.require_approval_tools));
    });
  }
  it("an answer without items is an error, not 'no tools'", () => {
    expect(() => planRunTools(normalizeToolCatalog({ error: "down" }))).toThrow(/no items/);
  });
  it("the run input carries the tools; with no layer the gateway's own grant decides approvals", () => {
    const plan = planRunTools(normalizeToolCatalog(cases[0].discovery));
    const input = withRunTools(buildRunInputData({ prompt: "hi" }), plan) as { tools: string[]; _runtime: Record<string, unknown> };
    expect(input.tools).toEqual(plan.tools);
    expect(input._runtime.allowed_tools).toEqual(plan.tools);
    expect("tool_policy" in input._runtime).toBe(false);
  });
});
